        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();

        // a[i][j] = buy price on planet i for item j
        // b[i][j] = sell price on planet i for item j
        // c[i][j] = available quantity on planet i for item j
        int[][] a = new int[n][m];
        int[][] b = new int[n][m];
        int[][] c = new int[n][m];

        for (int i = 0; i < n; i++) {
            sc.next(); // planet name
            for (int j = 0; j < m; j++) {
                a[i][j] = sc.nextInt();
                b[i][j] = sc.nextInt();
                c[i][j] = sc.nextInt();
            }
        }

        int maxProfit = 0;

        // Try all pairs of planets: buy on planet i, sell on planet j
        for (int buyPlanet = 0; buyPlanet < n; buyPlanet++) {
            for (int sellPlanet = 0; sellPlanet < n; sellPlanet++) {
                if (buyPlanet == sellPlanet) continue;

                // For each item type, compute the profit per item if we buy on buyPlanet and sell on sellPlanet
                // profit[j] = b[sellPlanet][j] - a[buyPlanet][j]
                // We can buy at most c[buyPlanet][j] items of type j
                // Total items <= k

                // This is a bounded knapsack problem:
                // We want to maximize sum over j of (profit[j] * x[j])
                // subject to sum x[j] <= k, 0 <= x[j] <= c[buyPlanet][j]
                // x[j] is integer

                // Since m and k are up to 100, we can use DP.
                // dp[items] = max profit using exactly 'items' items (or up to 'items')
                // Let's use dp[t] = max profit with t items total, for t from 0 to k

                int[] dp = new int[k + 1];
                // Initialize with 0 (we can always choose 0 items)
                // Actually, we want max profit, and profit can be negative, so we should be careful.
                // But we can always choose to buy 0 items, so profit 0 is always achievable.
                // Let's initialize dp with 0 and do standard bounded knapsack.

                // For each item type j, we can buy 0 to c[buyPlanet][j] items.
                // We'll use a 1D DP and iterate over items.

                // dp[t] = max profit achievable with t items
                // Initialize: dp[0] = 0, dp[t] = -infinity for t > 0? 
                // But since we can always have 0 items with 0 profit, and we're maximizing,
                // let's initialize all to 0 and only update when we get a better value.
                // Actually, let's use -infinity for unreachable states, but 0 items is always reachable.

                // Let me think again. We want max profit. We can buy any combination.
                // dp[t] = max profit with exactly t items.
                // dp[0] = 0
                // For t > 0, initially -infinity (unreachable)
                // But actually, we can also just track max profit for up to t items.

                // Let's use: dp[t] = max profit achievable with at most t items.
                // Then dp is non-decreasing.
                // Initialize dp[t] = 0 for all t (buying 0 items gives 0 profit).

                // For each item type j:
                //   profitPerItem = b[sellPlanet][j] - a[buyPlanet][j]
                //   maxQty = c[buyPlanet][j]
                //   For t from k down to 0:
                //       For qty from 1 to min(maxQty, k - t):
                //           dp[t + qty] = max(dp[t + qty], dp[t] + qty * profitPerItem)

                // But this is O(k * m * k) = O(k^2 * m) which is 100^2 * 100 = 10^6, acceptable.

                // Actually, let's use a cleaner approach. Standard bounded knapsack with 1D array.

                int[] dp2 = new int[k + 1];
                // dp2[t] = max profit with exactly t items
                // Initialize: dp2[0] = 0, others = Integer.MIN_VALUE / 2 (to avoid overflow)
                Arrays.fill(dp2, Integer.MIN_VALUE / 2);
                dp2[0] = 0;

                for (int j = 0; j < m; j++) {
                    int profitPerItem = b[sellPlanet][j] - a[buyPlanet][j];
                    int maxQty = c[buyPlanet][j];

                    // Create a new dp array for this item
                    int[] newDp = Arrays.copyOf(dp2, k + 1);

                    for (int t = 0; t <= k; t++) {
                        if (dp2[t] == Integer.MIN_VALUE / 2) continue;
                        for (int qty = 1; qty <= maxQty && t + qty <= k; qty++) {
                            int newT = t + qty;
                            int newProfit = dp2[t] + qty * profitPerItem;
                            if (newProfit > newDp[newT]) {
                                newDp[newT] = newProfit;
                            }
                        }
                    }

                    dp2 = newDp;
                }

                // The max profit for this pair of planets is the max over all t from 0 to k of dp2[t]
                for (int t = 0; t <= k; t++) {
                    if (dp2[t] > maxProfit) {
                        maxProfit = dp2[t];
                    }
                }
            }
        }

        System.out.println(maxProfit);
    }
}
