            for (int j = 0; j < m; j++) {
                a[i][j] = sc.nextInt();
                b[i][j] = sc.nextInt();
                c[i][j] = sc.nextInt();
            }
        }

        int maxProfit = 0;

        // Try all pairs of planets: buy on planet i, sell on planet j
        for (int buyPlanet = 0; buyPlanet < n; buyPlanet++) {
            for (int sellPlanet = 0; sellPlanet < n; sellPlanet++) {
                if (buyPlanet == sellPlanet) continue;

                // For each item type, compute the profit per item if bought on buyPlanet and sold on sellPlanet
                // profit per item j = b[sellPlanet][j] - a[buyPlanet][j]
                // We can buy at most c[buyPlanet][j] items of type j
                // We want to maximize total profit with at most k items total

                // This is a bounded knapsack problem:
                // Items: m types
                // For each type j:
                //   value = b[sellPlanet][j] - a[buyPlanet][j]
                //   weight = 1 (each item takes 1 unit of capacity)
                //   max count = c[buyPlanet][j]
                // Capacity = k

                // dp[x] = max profit using exactly x items (or at most x items)
                // We'll use dp where dp[x] = max profit with x items
                int[] dp = new int[k + 1];
                // Initialize to 0 (we can choose not to buy anything)

                // For each item type, do bounded knapsack
                for (int j = 0; j < m; j++) {
                    int profitPerItem = b[sellPlanet][j] - a[buyPlanet][j];
                    int maxCount = c[buyPlanet][j];

                    if (profitPerItem <= 0) {
                        // No profit from this item, skip
                        continue;
                    }

                    // Bounded knapsack: we can take 0 to maxCount items of type j
                    // Use the standard technique: for each item type, iterate backwards
                    // But since each item has weight 1 and same value, we can optimize
                    // Actually, let's just do the standard bounded knapsack with binary decomposition
                    // or simply iterate count from 1 to maxCount and update dp

                    // Simpler approach: for each possible number of items of this type (1 to maxCount),
                    // update dp from high to low
                    // But that's O(k * maxCount) per type, which is O(k * 100 * 100) = 10^6 per pair, 
                    // and there are at most 10*9=90 pairs, so 90 * 10^6 = 9*10^7 which might be tight.

                    // Better: use the "multiple knapsack" optimization with binary decomposition
                    // Or even simpler: since weight is 1, we can do:
                    // For each item type j with profit p and max count cnt:
                    //   for x from k down to 1:
                    //     dp[x] = max(dp[x], dp[x-1] + p)  -- but this only allows taking one at a time
                    //   Actually, we need to allow taking up to cnt items.

                    // Let's use the standard bounded knapsack with the trick:
                    // Convert to 0/1 knapsack using binary decomposition
                    int remaining = maxCount;
                    int power = 1;
                    while (remaining > 0) {
                        int take = Math.min(power, remaining);
                        // We have a "group" of 'take' items, each with profit profitPerItem
                        // Total profit for this group = take * profitPerItem
                        // Weight = take
                        int groupProfit = take * profitPerItem;
                        int groupWeight = take;

                        // 0/1 knapsack update: iterate from k down to groupWeight
                        for (int x = k; x >= groupWeight; x--) {
                            dp[x] = Math.max(dp[x], dp[x - groupWeight] + groupProfit);
                        }

                        remaining -= take;
                        power *= 2;
                    }
                }

                // The answer for this pair is the max over all x from 0 to k of dp[x]
                for (int x = 0; x <= k; x++) {
                    if (dp[x] > maxProfit) {
                        maxProfit = dp[x];
                    }
                }
            }
        }

