                    int[] newDp = Arrays.copyOf(dp, k + 1);

                    // For each current total items t, and for each possible count x of this item type
                    for (int t = 0; t <= k; t++) {
                        if (dp[t] == Integer.MIN_VALUE / 2) continue;
                        // We can add x items of type j, where 0 <= x <= maxCount and t + x <= k
                        int maxAdd = Math.min(maxCount, k - t);
                        for (int x = 1; x <= maxAdd; x++) {
                            int newT = t + x;
                            int newProfit = dp[t] + x * profitPerUnit;
                            if (newProfit > newDp[newT]) {
                                newDp[newT] = newProfit;
                            }
                        }
                    }

                    dp = newDp;
                }

                // Find the max profit over all possible total items (0 to k)
                for (int t = 0; t <= k; t++) {
                    if (dp[t] > maxProfit) {
                        maxProfit = dp[t];
                    }
                }
            }
        }

        System.out.println(maxProfit);
    }
}
